from collections import Counter
# find cells that changed and their components
H,W=len(inp),len(inp[0])
def comps(g,color):
    seen=set(); res=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==color and (i,j) not in seen:
                stack=[(i,j)]; seen.add((i,j)); c=[]
                while stack:
                    y,x=stack.pop(); c.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==color and (ny,nx) not in seen:
                            seen.add((ny,nx)); stack.append((ny,nx))
                res.append(c)
    return res
