def f(g):
    Hh,Ww=len(g),len(g[0])
    out=[r[:] for r in g]
    for i in range(Hh):
        for j in range(Ww):
            c=Counter()
            for di in(0,1):
                for dj in(0,1):
                    y0,x0=i-di,j-dj
                    if 0<=y0<Hh-0 and 0<=x0<Ww-0 and y0+1<Hh and x0+1<Ww:
                        for yy in(y0,y0+1):
                            for xx in(x0,x0+1):
                                c[g[yy][xx]]+=1
            if c:
                best=c.most_common()
                # tie-break: keep own color if tied for top
                top=best[0][1]
                cands=[k for k,v in best if v==top]
                new=g[i][j] if g[i][j] in cands else cands[0]
                out[i][j]=new
    return out
