def f(g):
    Hh,Ww=len(g),len(g[0])
    out=[r[:] for r in g]
    for i in range(Hh):
        for j in range(Ww):
            score=Counter()  # color -> best square count
            for di in(0,1):
                for dj in(0,1):
                    y0,x0=i-di,j-dj
                    if 0<=y0 and x0>=0 and y0+1<Hh and x0+1<Ww:
                        c=Counter(g[yy][xx] for yy in(y0,y0+1) for xx in(x0,x0+1))
                        for col,v in c.items():
                            score[col]=max(score[col],v)
            best=max(score.items(), key=lambda kv:(kv[1], kv[0]==g[i][j]))
            out[i][j]=best[0]
    return out
